import java.util.*;

class Solution {
  public void wiggleSort(int[] nums) {
    int n = nums.length;
    int[] sorted = nums.clone();
    Arrays.sort(sorted);
    // fill even slots from the middle down and odd slots from the top down, so equal values never touch
    int small = (n - 1) / 2, large = n - 1;
    for (int k = 0; k < n; k++) nums[k] = k % 2 == 0 ? sorted[small--] : sorted[large--];
  }
}
